import pathlib
FILES = {
    'src/main/java/com/example/fpvdrone/capability/PlayerDroneCapability.java': 'package com.example.fpvdrone.capability;\n\nimport net.minecraft.nbt.CompoundTag;\n\nimport java.util.UUID;\n\npublic class PlayerDroneCapability {\n    private UUID boundDroneUuid;\n    private int boundDroneEntityId = -1;\n\n    public UUID getBoundDroneUuid() {\n        return boundDroneUuid;\n    }\n\n    public int getBoundDroneEntityId() {\n        return boundDroneEntityId;\n    }\n\n    public boolean isPiloting() {\n        return boundDroneUuid != null;\n    }\n\n    public void bindDrone(UUID uuid, int entityId) {\n        this.boundDroneUuid = uuid;\n        this.boundDroneEntityId = entityId;\n    }\n\n    public void clearBinding() {\n        this.boundDroneUuid = null;\n        this.boundDroneEntityId = -1;\n    }\n\n    public void copyFrom(PlayerDroneCapability other) {\n        this.boundDroneUuid = other.boundDroneUuid;\n        this.boundDroneEntityId = other.boundDroneEntityId;\n    }\n\n    public CompoundTag serializeNBT() {\n        CompoundTag tag = new CompoundTag();\n        if (boundDroneUuid != null) {\n            tag.putUUID("BoundDroneUuid", boundDroneUuid);\n        }\n        tag.putInt("BoundDroneEntityId", boundDroneEntityId);\n        return tag;\n    }\n\n    public void deserializeNBT(CompoundTag tag) {\n        if (tag.hasUUID("BoundDroneUuid")) {\n            boundDroneUuid = tag.getUUID("BoundDroneUuid");\n        } else {\n            boundDroneUuid = null;\n        }\n        boundDroneEntityId = tag.contains("BoundDroneEntityId") ? tag.getInt("BoundDroneEntityId") : -1;\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/client/renderer/FpvDroneRenderer.java': 'package com.example.fpvdrone.client.renderer;\n\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.mojang.blaze3d.vertex.PoseStack;\nimport net.minecraft.client.renderer.MultiBufferSource;\nimport net.minecraft.client.renderer.entity.EntityRendererProvider;\nimport org.joml.Quaternionf;\nimport software.bernie.geckolib.renderer.GeoEntityRenderer;\n\npublic class FpvDroneRenderer extends GeoEntityRenderer<FpvDroneEntity> {\n    public FpvDroneRenderer(EntityRendererProvider.Context renderManager) {\n        super(renderManager, new FpvDroneModel());\n        this.shadowRadius = 0.35F;\n    }\n\n    @Override\n    public void render(FpvDroneEntity entity, float entityYaw, float partialTick,\n                       PoseStack poseStack, MultiBufferSource bufferSource, int packedLight) {\n        poseStack.pushPose();\n        poseStack.translate(0.0D, 0.15D, 0.0D);\n        Quaternionf q = entity.getInterpolatedOrientation(partialTick);\n        poseStack.mulPose(q);\n        poseStack.translate(0.0D, -0.15D, 0.0D);\n        super.render(entity, entityYaw, partialTick, poseStack, bufferSource, packedLight);\n        poseStack.popPose();\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/item/FpvDroneItem.java': 'package com.example.fpvdrone.item;\n\nimport com.example.fpvdrone.capability.PlayerDroneProvider;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.network.S2CDroneTelemetryPacket;\nimport com.example.fpvdrone.registry.ModEntities;\nimport com.example.fpvdrone.registry.ModItems;\nimport com.example.fpvdrone.registry.ModSounds;\nimport net.minecraft.core.BlockPos;\nimport net.minecraft.core.Direction;\nimport net.minecraft.server.level.ServerLevel;\nimport net.minecraft.server.level.ServerPlayer;\nimport net.minecraft.sounds.SoundSource;\nimport net.minecraft.world.InteractionResult;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.entity.player.Player;\nimport net.minecraft.world.item.Item;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.context.UseOnContext;\nimport net.minecraft.world.level.Level;\nimport net.minecraft.world.phys.Vec3;\n\npublic class FpvDroneItem extends Item {\n    public FpvDroneItem(Properties properties) {\n        super(properties);\n    }\n\n    @Override\n    public InteractionResult useOn(UseOnContext context) {\n        Level level = context.getLevel();\n        Player player = context.getPlayer();\n        if (player == null) {\n            return InteractionResult.PASS;\n        }\n\n        if (!(level instanceof ServerLevel serverLevel) || !(player instanceof ServerPlayer serverPlayer)) {\n            return InteractionResult.SUCCESS;\n        }\n\n        BlockPos clickedPos = context.getClickedPos();\n        Direction face = context.getClickedFace();\n        Vec3 spawnPos = Vec3.atCenterOf(clickedPos).add(\n                face.getStepX() * 0.65,\n                face.getStepY() * 0.65 + 0.15,\n                face.getStepZ() * 0.65\n        );\n\n        FpvDroneEntity drone = ModEntities.FPV_DRONE.get().create(serverLevel);\n        if (drone == null) {\n            return InteractionResult.FAIL;\n        }\n\n        drone.setPos(spawnPos.x, spawnPos.y, spawnPos.z);\n        drone.setOwnerUuid(serverPlayer.getUUID());\n        drone.setInitialYaw(serverPlayer.getYRot());\n        serverLevel.addFreshEntity(drone);\n\n        // Auto-equip goggles onto HEAD slot, safely preserving any existing helmet\n        ItemStack existingHead = serverPlayer.getItemBySlot(EquipmentSlot.HEAD);\n        ItemStack gogglesStack;\n        if (existingHead.getItem() instanceof FpvGogglesItem) {\n            gogglesStack = existingHead;\n        } else {\n            if (!existingHead.isEmpty()) {\n                ItemStack toMove = existingHead.copy();\n                if (!serverPlayer.getInventory().add(toMove)) {\n                    serverPlayer.drop(toMove, false);\n                }\n            }\n            gogglesStack = new ItemStack(ModItems.FPV_GOGGLES.get());\n            serverPlayer.setItemSlot(EquipmentSlot.HEAD, gogglesStack);\n        }\n        FpvGogglesItem.setBoundDroneUuid(gogglesStack, drone.getUUID());\n\n        // Bind drone to PlayerDroneCapability\n        serverPlayer.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(cap ->\n                cap.bindDrone(drone.getUUID(), drone.getId()));\n\n        // Play ESC arming beep\n        serverLevel.playSound(null, serverPlayer.getX(), serverPlayer.getY(), serverPlayer.getZ(),\n                ModSounds.DRONE_ARM_BEEP.get(), SoundSource.PLAYERS, 0.85F, 1.0F);\n\n        // Notify client to switch camera POV immediately\n        PacketHandler.sendToPlayer(\n                new S2CDroneTelemetryPacket(\n                        drone.getId(),\n                        drone.getUUID(),\n                        drone.getThrottle(),\n                        drone.getBatteryVoltage(),\n                        drone.getFlightTicks(),\n                        true\n                ),\n                serverPlayer\n        );\n\n        if (!serverPlayer.getAbilities().instabuild) {\n            context.getItemInHand().shrink(1);\n        }\n\n        return InteractionResult.CONSUME;\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/network/PacketHandler.java': 'package com.example.fpvdrone.network;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.server.level.ServerPlayer;\nimport net.minecraftforge.network.NetworkDirection;\nimport net.minecraftforge.network.NetworkRegistry;\nimport net.minecraftforge.network.PacketDistributor;\nimport net.minecraftforge.network.simple.SimpleChannel;\n\npublic class PacketHandler {\n    private static final String PROTOCOL_VERSION = "1";\n    public static final SimpleChannel INSTANCE = NetworkRegistry.newSimpleChannel(\n            new ResourceLocation(FpvDroneMod.MODID, "main"),\n            () -> PROTOCOL_VERSION,\n            PROTOCOL_VERSION::equals,\n            PROTOCOL_VERSION::equals\n    );\n\n    private static int packetId = 0;\n\n    public static void register() {\n        INSTANCE.messageBuilder(C2SDroneControlPacket.class, packetId++, NetworkDirection.PLAY_TO_SERVER)\n                .encoder(C2SDroneControlPacket::encode)\n                .decoder(C2SDroneControlPacket::decode)\n                .consumerMainThread(C2SDroneControlPacket::handle)\n                .add();\n\n        INSTANCE.messageBuilder(S2CDroneTelemetryPacket.class, packetId++, NetworkDirection.PLAY_TO_CLIENT)\n                .encoder(S2CDroneTelemetryPacket::encode)\n                .decoder(S2CDroneTelemetryPacket::decode)\n                .consumerMainThread(S2CDroneTelemetryPacket::handle)\n                .add();\n\n        INSTANCE.messageBuilder(S2CDroneDestroyedPacket.class, packetId++, NetworkDirection.PLAY_TO_CLIENT)\n                .encoder(S2CDroneDestroyedPacket::encode)\n                .decoder(S2CDroneDestroyedPacket::decode)\n                .consumerMainThread(S2CDroneDestroyedPacket::handle)\n                .add();\n    }\n\n    public static <MSG> void sendToServer(MSG message) {\n        INSTANCE.sendToServer(message);\n    }\n\n    public static <MSG> void sendToPlayer(MSG message, ServerPlayer player) {\n        INSTANCE.send(PacketDistributor.PLAYER.with(() -> player), message);\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/registry/ModCreativeTabs.java': 'package com.example.fpvdrone.registry;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport net.minecraft.core.registries.Registries;\nimport net.minecraft.network.chat.Component;\nimport net.minecraft.world.item.CreativeModeTab;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraftforge.registries.DeferredRegister;\nimport net.minecraftforge.registries.RegistryObject;\n\npublic class ModCreativeTabs {\n    public static final DeferredRegister<CreativeModeTab> CREATIVE_TABS =\n            DeferredRegister.create(Registries.CREATIVE_MODE_TAB, FpvDroneMod.MODID);\n\n    public static final RegistryObject<CreativeModeTab> FPV_DRONE_TAB = CREATIVE_TABS.register("fpvdrone_tab",\n            () -> CreativeModeTab.builder()\n                    .title(Component.translatable("creativetab.fpvdrone_tab"))\n                    .icon(() -> new ItemStack(ModItems.FPV_DRONE_ITEM.get()))\n                    .displayItems((params, output) -> {\n                        output.accept(ModItems.FPV_DRONE_ITEM.get());\n                        output.accept(ModItems.FPV_GOGGLES.get());\n                    })\n                    .build());\n}\n',
    'src/main/resources/META-INF/mods.toml': 'modLoader="javafml"\nloaderVersion="${loader_version_range}"\nlicense="${mod_license}"\n\n[[mods]]\nmodId="${mod_id}"\nversion="${mod_version}"\ndisplayName="${mod_name}"\nauthors="${mod_authors}"\ndescription=\'\'\'${mod_description}\'\'\'\n\n[[dependencies.${mod_id}]]\n    modId="forge"\n    mandatory=true\n    versionRange="${forge_version_range}"\n    ordering="NONE"\n    side="BOTH"\n\n[[dependencies.${mod_id}]]\n    modId="minecraft"\n    mandatory=true\n    versionRange="${minecraft_version_range}"\n    ordering="NONE"\n    side="BOTH"\n\n[[dependencies.${mod_id}]]\n    modId="geckolib"\n    mandatory=true\n    versionRange="[4.4.4,)"\n    ordering="AFTER"\n    side="BOTH"\n',
    'src/main/resources/assets/fpvdrone/lang/en_us.json': '{\n  "item.fpvdrone.fpv_drone_item": "FPV Combat Drone",\n  "item.fpvdrone.fpv_goggles": "FPV Analog Goggles",\n  "entity.fpvdrone.fpv_drone": "FPV Combat Drone",\n  "creativetab.fpvdrone_tab": "FPV Combat Drone",\n  "sound.fpvdrone.drone_motor_loop": "Drone Brushless Motors",\n  "sound.fpvdrone.drone_arm_beep": "Drone ESC Arming Chime",\n  "sound.fpvdrone.signal_static_loop": "Analog Video Static",\n  "sound.fpvdrone.drone_explosion": "Drone Warhead Detonation",\n  "tooltip.fpvdrone.goggles_bound": "Bound Drone: %s",\n  "tooltip.fpvdrone.goggles_unbound": "No Active Drone Link"\n}\n',
}
for k, v in FILES.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Wrote", len(FILES), "files")
